#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>
#include <WiFi.h>

// --- Настройки OLED ---
#define SCREEN_WIDTH 128
#define SCREEN_HEIGHT 64
#define OLED_RESET -1
#define SCREEN_ADDRESS 0x3C

Adafruit_SSD1306 display(SCREEN_WIDTH, SCREEN_HEIGHT, &Wire, OLED_RESET);

// --- Настройки кнопок (более безопасные пины) ---
#define BTN_UP     1
#define BTN_DOWN   2
#define BTN_SELECT 3   // было 0 — заменил на 3

// --- Переменные ---
int networkCount = 0;
int selectedNetwork = 0;
bool needsRedraw = true;

// --- Антидребезг ---
unsigned long lastBtnTime = 0;
const unsigned long DEBOUNCE_MS = 200;

void setup() {
  Serial.begin(115200);

  pinMode(BTN_UP, INPUT_PULLUP);
  pinMode(BTN_DOWN, INPUT_PULLUP);
  pinMode(BTN_SELECT, INPUT_PULLUP);

  if (!display.begin(SSD1306_SWITCHCAPVCC, SCREEN_ADDRESS)) {
    Serial.println(F("SSD1306 init failed. Try address 0x3D."));
    for (;;);
  }

  display.clearDisplay();
  display.setTextSize(1);
  display.setTextColor(SSD1306_WHITE);
  display.setCursor(0, 0);
  display.println("WiFi Scanner");
  display.display();
  delay(1000);

  WiFi.mode(WIFI_STA);
  WiFi.disconnect();
  delay(100);

  scanWiFi();
}

void loop() {
  unsigned long now = millis();

  if (now - lastBtnTime > DEBOUNCE_MS) {
    if (digitalRead(BTN_UP) == LOW) {
      if (selectedNetwork > 0) selectedNetwork--;
      needsRedraw = true;
      lastBtnTime = now;
    }

    if (digitalRead(BTN_DOWN) == LOW) {
      if (selectedNetwork < networkCount - 1) selectedNetwork++;
      needsRedraw = true;
      lastBtnTime = now;
    }

    if (digitalRead(BTN_SELECT) == LOW) {
      scanWiFi();
      selectedNetwork = 0;
      needsRedraw = true;
      lastBtnTime = now;
    }
  }

  if (needsRedraw) {
    drawMenu();
    needsRedraw = false;
  }
}

void scanWiFi() {
  display.clearDisplay();
  display.setCursor(0, 0);
  display.println("Scanning...");
  display.display();

  // Удаляем старые результаты
  WiFi.scanDelete();

  networkCount = WiFi.scanNetworks();

  if (networkCount < 0) networkCount = 0;

  // Ограничиваем для отображения
  if (networkCount > 5) networkCount = 5;

  // Корректируем выбор
  if (selectedNetwork >= networkCount) selectedNetwork = 0;
}

void drawMenu() {
  display.clearDisplay();

  if (networkCount == 0) {
    display.setCursor(0, 0);
    display.println("No networks found");
    display.setCursor(0, 20);
    display.println("Press SEL to rescan");
    display.display();
    return;
  }

  for (int i = 0; i < networkCount; i++) {
    int yPos = i * 12;

    if (i == selectedNetwork) {
      display.fillRect(0, yPos, 128, 12, SSD1306_WHITE);
      display.setTextColor(SSD1306_BLACK);
    } else {
      display.setTextColor(SSD1306_WHITE);
    }

    display.setCursor(0, yPos + 2);

    String ssid = WiFi.SSID(i);
    if (ssid.length() > 16) ssid = ssid.substring(0, 16);
    if (ssid.length() == 0) ssid = "(hidden)";
    display.print(ssid);

    display.setCursor(100, yPos + 2);
    display.print(WiFi.RSSI(i));
  }

  display.display();
}
